      def: "強み（Strengths）・弱み（Weaknesses）の内部要因と、機会（Opportunities）・脅威（Threats）の外部環境を整理する手法。クロスSWOTで戦略オプションを導く。",
      ex: "コンビニ各社では、物価高による節約志向（脅威）を、PBや小型スーパー業態（機会への対応）で取り込む戦略が2026年に分かれ目となった。",
