      def: "年金・医療・介護・子育て支援などの給付にかかる費用。高齢化で増え続け、国の一般会計歳出の約3分の1を占める最大の項目になっている。",
      ex: "少子化対策の財源として、医療保険料に上乗せして集める「子ども・子育て支援金」の徴収が2026年度から始まった。",
