      def: "純資産は資産から負債を引いたもの。株主資本（資本金・資本剰余金・利益剰余金・自己株式）が中心で、ほかに評価・換算差額等、新株予約権、非支配株主持分を含む。一般に自己資本は、純資産から新株予約権と非支配株主持分を除いたもの。",
